use eframe::egui;
pub const SCENES:&[&str]=&["icon-catalog","chrome-demo","text-basic","folder-basic","table-basic"];
pub fn is_scene(s:Option<&str>)->bool{s.is_some_and(|v|SCENES.contains(&v))}
pub fn demo(ui:&mut egui::Ui,scene:&str){ui.heading(format!("Matcha · {scene}"));let menus=vec![crate::chrome::menubar::MenuSpec{title:"File".into(),mnemonic:Some('F'),items:vec![crate::chrome::menubar::Item{label:"Open".into(),mnemonic:Some('O'),shortcut:Some("Ctrl+O".into()),kind:crate::chrome::menubar::ItemKind::Action,enabled:true,action_id:"open".into()}]}];let _=crate::chrome::menubar::show(ui,&menus);let tools=vec![crate::chrome::toolbar::ToolItem{label:"Home".into(),action_id:"home".into(),kind:crate::chrome::toolbar::ButtonKind::Normal,selected:false},crate::chrome::toolbar::ToolItem{label:"Diffs".into(),action_id:"diffs".into(),kind:crate::chrome::toolbar::ButtonKind::Toggle,selected:true}];let _=crate::chrome::toolbar::show(ui,&tools);let mut path="C:\\work\\left.txt".to_string();let _=crate::chrome::pathbar::show(ui,&mut path);crate::chrome::statusbar::show(ui,&[crate::chrome::statusbar::StatusField{text:"Ready".into(),width:Some(180.0)},crate::chrome::statusbar::StatusField{text:"0 differences".into(),width:None}]);ui.separator();if scene=="icon-catalog"{ui.horizontal_wrapped(|ui|{for i in [crate::chrome::icons::Icon::Home,crate::chrome::icons::Icon::Sessions,crate::chrome::icons::Icon::Diffs,crate::chrome::icons::Icon::Copy,crate::chrome::icons::Icon::Refresh,crate::chrome::icons::Icon::Folder,crate::chrome::icons::Icon::File]{let(r,_)=ui.allocate_exact_size(egui::vec2(64.0,48.0),egui::Sense::hover());crate::chrome::icons::paint(ui.painter(),r,i);}});}}
